  public static class SetupServiceProbe {
    public static async Task<ZapretCheckRow> Measure(NetworkCore core,IEnumerable<ZapretService> services,bool proxy,CancellationToken token,Action<string> progress,Action<ZapretCheckRow> live=null){
      var row=new ZapretCheckRow{Name=proxy?"Через VPN":"Без обхода",CheckedAt=DateTime.Now,Checking=true};if(live!=null)live(row);
      using(var video=new VideoProbe(core.CurlExecutable,(proxy?"--noproxy \"\" --proxy socks5h://127.0.0.1:10808 ":"--noproxy \"*\" ")+"--cacert "+ZapretRuntime.Quote(Path.Combine(core.DataRoot,"core","curl-ca-bundle.crt"))))
      using(var gate=new SemaphoreSlim(4)){
        var tasks=services.Select(async service=>{
          var rounds=new List<ZapretEndpointResult[]>();
for(int round=0;round<(service.Urls.Length==1&&(service.Urls[0]==VideoProbe.Target||service.Urls[0]==VideoProbe.PornhubTarget||ServiceBrowserProbe.Supports(service.Urls[0]))?1:2);round++){
            var results=await Task.WhenAll(service.Urls.Select(async url=>{
              await gate.WaitAsync(token);try{return url==VideoProbe.Target||url==VideoProbe.PornhubTarget?await video.RunMediaFor(url,token):await Probe(core,url,proxy,token);}finally{gate.Release();}
            }));rounds.Add(results);
          }
          var result=ZapretChecks.Combine(service,rounds[0],rounds.Count==1?new ZapretEndpointResult[0]:rounds[1]);lock(row.Services)row.Services.Add(result);
          if(progress!=null)progress(service.Name+": "+ZapretChecks.Label(result.Access));
        }).ToArray();await Task.WhenAll(tasks);
      }row.Checking=false;return row;
    }
    static async Task<ZapretEndpointResult> Probe(NetworkCore core,string url,bool proxy,CancellationToken token){
      if(url==DiscordInterfaceProbe.Target)return await DiscordInterfaceProbe.Run(proxy,token);
if(ServiceBrowserProbe.Supports(url))return await ServiceBrowserProbe.Run(Path.Combine(core.DataRoot,"core"),url,proxy?"socks5://127.0.0.1:10808":null,token,null,HostsCandidates.StrategyBudgetMs);
      string args="--silent --show-error --location --max-redirs 3 --proto =https --proto-redir =https --http1.1 --compressed --dump-header - --header \"Connection: close\" --user-agent \"Mozilla/5.0\" "+(proxy?"--noproxy \"\" --proxy socks5h://127.0.0.1:10808 ":"--noproxy \"*\" ")+"--connect-timeout 3 --max-time 5 --cacert "+ZapretRuntime.Quote(Path.Combine(core.DataRoot,"core","curl-ca-bundle.crt"))+" --write-out \"\nMCRF_HTTP:%{http_code}\" "+ZapretRuntime.Quote(url);
      return await BoundedProbe.Run(core.CurlExecutable,args,url,token);
    }
  }
