        intro.Text=step==0?"Есть свой VPN? Выберите подходящий вариант.":step==1?(mode.SelectedIndex==0?"Добавьте или выберите VPN, затем настройте его маршруты и DNS.":"Выберите сервисы и наборы стратегий. После проверки предложим отдельные выходы."):step==2?"Видео проверяется воспроизведением; голос Discord — отдельным шагом. Настройки ещё не применяются.":"Проверьте распределение сервисов. Настройки изменятся только по кнопке «Применить план».";
        previous.Visible=step>0;previous.Enabled=forward.Enabled=!busy;forward.Visible=step<2&&(mode.SelectedIndex==0||step==0);forward.Text=step==1&&mode.SelectedIndex==0?"Сохранить":"Далее";cancel.Text=busy?"Отменить проверку":"Закрыть";
        if(step==0){mode.Visible=true;mode.SetBounds(22,110,Math.Min(380,box.Width-44),42);}
        if(step==1&&mode.SelectedIndex==0){vpnLinkHost.Visible=addVpn.Visible=importServers.Visible=chooseRoutes.Visible=vpnDnsLabel.Visible=vpnDns.Visible=true;vpnLinkHost.SetBounds(22,112,box.Width-192,42);addVpn.SetBounds(box.Width-156,112,134,42);importServers.SetBounds(22,170,box.Width-44,42);chooseRoutes.SetBounds(22,228,box.Width-44,42);vpnDnsLabel.SetBounds(22,296,box.Width-44,26);bool specific=vpnDns.SelectedIndex>=2;vpnDns.SetBounds(22,332,box.Width-(specific?220:44),42);vpnDnsType.Visible=specific;vpnDnsType.SetBounds(box.Width-188,332,166,42);vpnDnsHost.Visible=specific&&vpnDns.SelectedItem=="Свой";vpnDnsHost.SetBounds(22,382,box.Width-44,42);vpnDnsCustom.Width=vpnDnsHost.Width-24;}
        if(step==1&&mode.SelectedIndex==1){check.Visible=true;useSaved.Visible=cachedReport!=null&&cachedReport.Complete;useSaved.SetBounds(22,272,Math.Min(380,box.Width-44),40);services.Visible=true;services.SetBounds(22,112,box.Width-44,42);families.Visible=true;families.SetBounds(22,174,box.Width-44,42);}
        if(step==2){check.Visible=!busy;}
        if(step>=2){journalHost.Visible=true;journalHost.SetBounds(22,step==2&&mode.SelectedIndex==0?290:180,box.Width-44,Math.Max(60,box.Height-(step==2&&mode.SelectedIndex==0?400:290)));clear.Visible=true;}
        if(step==3){apply.Visible=results.Visible=true;results.SetBounds(box.Width-222,112,200,40);strategies.Visible=assignments==null&&ranked.Length>0;strategies.SetBounds(22,112,box.Width-264,42);}
        buttons.Controls.SetChildIndex(previous,0);buttons.Controls.SetChildIndex(forward,1);
      };refreshSteps=paintSteps;
      mode.SelectedIndexChanged+=(s,e)=>{moduleChoices.SetChecked(0,mode.SelectedIndex==1);step=0;paintSteps();};moduleChoices.CheckedItemsChanged+=(s,e)=>paintSteps();
      check.EnabledChanged+=(s,e)=>{if(!busy&&apply.Enabled)step=3;paintSteps();};
paintSteps();box.Disposed+=(s,e)=>{if(setupCancellation!=null)setupCancellation.Cancel();if(stagedTelegramOwned&&!planApplied){telegramBridge.Stop();stagedTelegramOwned=false;}};
    }
    static string SetupDestinationLabel(string value){return value=="direct"?"напрямую":value=="zapret"?"Zapret":value=="proxy"?"VPN":"нет подтверждённого пути";}
    async Task<ZapretCheckRow> MeasureSetupLive(NetworkCore network,ZapretService[] services,bool proxy,CancellationTokenSource cancellation,Action<string> progress){if(services.Length==0)return new ZapretCheckRow{Name="Без обхода",Services=new List<ZapretServiceResult>()};var report=new ZapretCheckReport{Settings=new ZapretSettings{CheckServices=services.Select(x=>x.Id).ToList()},ServiceIds=services.Select(x=>x.Id).ToList()};var live=OpenLiveResults(report,proxy?"Мастер · VPN / WARP":"Мастер · без обхода",cancellation);try{var row=await SetupServiceProbe.Measure(network,services,proxy,cancellation.Token,progress,value=>report.Rows.Add(value));report.Complete=true;return row;}finally{live.Finish();}}
    Control ShowSetupResults(ZapretCheckReport report,Action<ZapretCheckRow> choose,Action<ZapretCheckRow,ZapretService> chooseService=null){
      Panel veil=UiTheme.Simple?(Panel)new Panel{Name="mainResultSection",Location=new Point(234,72),Size=new Size(ClientSize.Width-250,ClientSize.Height-88),Anchor=AnchorStyles.Top|AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right,BackColor=Color.FromArgb(12,17,31)}:new GlassBackdrop(blueDashboard){Dock=DockStyle.Fill};var popup=new GlassPopupPanel{Inline=UiTheme.Simple,Size=new Size(Math.Min(1300,ClientSize.Width-40),Math.Min(620,ClientSize.Height-40))};veil.Controls.Add(popup);Action layout=()=>{if(UiTheme.Simple)popup.SetBounds(0,0,veil.Width,veil.Height);else popup.Location=new Point((veil.Width-popup.Width)/2,(veil.Height-popup.Height)/2);};veil.Resize+=(s,e)=>layout();layout();
      var caption=L("Результаты · мастер · "+(report.FinishedAt==DateTime.MinValue?DateTime.Now-report.StartedAt:report.FinishedAt-report.StartedAt).ToString(@"hh\:mm\:ss"),18,true);caption.SetBounds(24,20,popup.Width-110,40);popup.Controls.Add(caption);
      var close=new GlassClose{Location=new Point(popup.Width-64,20)};close.Click+=(s,e)=>veil.Dispose();if(!UiTheme.Simple)popup.Controls.Add(close);else{var back=B("Назад",(s,e)=>veil.Dispose());back.SetBounds(popup.Width-148,popup.Height-47,124,36);back.Anchor=AnchorStyles.Bottom|AnchorStyles.Right;popup.Controls.Add(back);}
      var table=new ZapretResultTable{VisibleServices=ZapretChecks.Selected(report.ServiceIds??report.Settings.CheckServices).Concat(report.Rows.Any(r=>r.Services.Any(v=>v.Id=="discord-voice"))?new[]{DiscordVoiceScores.Service}:new ZapretService[0]).ToArray(),CanApply=choose!=null,ActionCaption="Выбрать",Rows=report.Rows.Where(x=>x.StrategyId==null).Concat(ZapretChecks.Rank(report.Rows)).ToArray()};table.SetBounds(24,80,popup.Width-48,popup.Height-140);table.Anchor=AnchorStyles.Top|AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right;popup.Controls.Add(table);table.CanApply=chooseService!=null;if(chooseService!=null)table.ApplyService+=(row,service)=>{chooseService(row,service);veil.Dispose();};
      var hint=L(report.MediaProbeRevision<2?"Сохранён прежний видеотест — для актуальных результатов повторите проверку.":choose==null?"Результаты проверки. Выбор выходов и стратегий выполняется отдельным шагом мастера.":"Выбор конфига не включает Zapret. Применение — кнопкой «Применить план» в мастере.",10,false,Muted);hint.AutoSize=false;hint.SetBounds(24,popup.Height-50,popup.Width-(UiTheme.Simple?190:48),40);hint.Anchor=AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right;popup.Controls.Add(hint);Controls.Add(veil);veil.BringToFront();layout();return veil;
